func evens(nums []int) []int {
    var out []int
    for _, n := range nums {
        if n%2 == 0 {
            out = append(out, n)
        }
    }
    return out
}

func main() {
    fmt.Println(evens([]int{1, 2, 3, 4}))
    none := evens([]int{1, 3})
    fmt.Println(none, none == nil)
}

